import { Link } from "react-router-dom";
import { portfolioData } from "../data/portfolioData";
import ScrollSection from "../components/ScrollSection";

export default function Home() {
  const greeting = portfolioData.greeting.replace("{name}", portfolioData.name);

  return (
    <main>
      <section className="hero-section">
        {portfolioData.heroKeywords.map((item, index) => (
          <h1 key={item.title} className="hero-keyword">
            {index === 2 ? (
              <>
                {item.title}
                <br />
                IMPROVEMENT
              </>
            ) : (
              item.title
            )}
          </h1>
        ))}
        <p className="hero-greeting">{greeting}</p>
      </section>

      <ScrollSection>
        <div className="value-grid">
          {portfolioData.heroKeywords.map((item) => (
            <article key={item.title} className="value-card">
              <h2 className="value-card-title">{item.title}</h2>
              <p className="value-card-desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </ScrollSection>

      <ScrollSection>
        <p className="section-label">{portfolioData.overview.title}</p>
        <h2 className="section-title">{portfolioData.overview.subtitle}</h2>
        <p className="section-body">{portfolioData.overview.description}</p>

        <div className="overview-links">
          {portfolioData.overview.links.map((link) => (
            <Link key={link.to} to={link.to} className="overview-link">
              <h3 className="overview-link-title">{link.title}</h3>
              <p className="overview-link-desc">{link.desc}</p>
            </Link>
          ))}
        </div>
      </ScrollSection>
    </main>
  );
}
